<div class="page-intro"><div><span class="eyebrow">TRANSACTIONS</span><h2>Sales history</h2><p>Every recorded sale, with its product, customer, and staff member.</p></div><a class="btn primary" href="<?= site_url('terminal') ?>">+ Record sale</a></div><div class="panel table-wrap"><table><thead><tr><th>Sale ID</th><th>Product</th><th>Customer</th><th>Sold by</th><th>Quantity</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong>#<?= esc($row['id']) ?></strong></td><td><?= esc($row['product_name']) ?></td><td><?= esc($row['customer_name'] ?: 'Walk-in Customer') ?></td><td><?= esc($row['staff_name']) ?></td><td><?= esc($row['quantity']) ?></td><td><strong>₱<?= number_format((float)$row['total_price'],2) ?></strong></td><td><?= esc($row['created_at']) ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="7" class="empty">No sales recorded yet.</td></tr><?php endif ?></tbody></table></div>
